/*!40000 ALTER TABLE `exercise_items` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `exercises`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `exercises` (
  `exercise_id` bigint NOT NULL AUTO_INCREMENT,
  `category_id` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `instruction` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `input_type` enum('mic','read','speak') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'mic',
  `target_phonemes` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` smallint NOT NULL DEFAULT '0',
  `active` tinyint(1) NOT NULL DEFAULT '1',
  `difficulty` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `content_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pronunciation_rule` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`exercise_id`),
  KEY `idx_exercise_category` (`category_id`,`active`,`sort_order`),
  KEY `idx_exercise_filters` (`active`,`pronunciation_rule`,`difficulty`,`content_type`),
  CONSTRAINT `fk_exercise_category` FOREIGN KEY (`category_id`) REFERENCES `practice_categories` (`category_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1246 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

