DROP TABLE IF EXISTS `practice_attempts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `practice_attempts` (
  `attempt_id` bigint NOT NULL AUTO_INCREMENT,
  `student_id` bigint NOT NULL,
  `exercise_id` bigint NOT NULL,
  `item_id` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `analysis_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `score` decimal(5,2) DEFAULT NULL,
  `match_rate` decimal(5,2) DEFAULT NULL,
  `attempt_type` enum('PRACTICE','HOMEWORK','AI_CHAT','SELF','LESSON') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PRACTICE',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `homework_id` bigint DEFAULT NULL,
  PRIMARY KEY (`attempt_id`),
  UNIQUE KEY `uq_attempt_analysis` (`analysis_id`),
  KEY `idx_attempt_student_date` (`student_id`,`created_at` DESC),
  KEY `fk_attempt_exercise` (`exercise_id`),
  KEY `fk_attempt_homework` (`homework_id`),
  CONSTRAINT `fk_attempt_analysis` FOREIGN KEY (`analysis_id`) REFERENCES `speech_analyses` (`analysis_id`),
  CONSTRAINT `fk_attempt_exercise` FOREIGN KEY (`exercise_id`) REFERENCES `exercises` (`exercise_id`),
  CONSTRAINT `fk_attempt_homework` FOREIGN KEY (`homework_id`) REFERENCES `homeworks` (`homework_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_attempt_student` FOREIGN KEY (`student_id`) REFERENCES `student_profiles` (`student_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
